interface.signature:
POST /api/gomafia-sync/import
Request Body: { profileUrl: string } | { playerId: string }
Response: { jobId: string, status: string, message: string }

GET /api/gomafia-sync/import/status?jobId={jobId}
Response: { 
  percentageComplete: number, 
  currentGameNumber: number, 
  totalGames: number, 
  estimatedTimeRemaining: number, 
  currentPhase: string,
  status: 'running' | 'completed' | 'failed' | 'paused'
}
